import{_ as a,a as s,c as o,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · 单元 3 复习与自测 · 第49–57课","description":"L49–L72 原创练习和答案解析。","frontmatter":{"title":"第二册：实践与进步 · 单元 3 复习与自测 · 第49–57课","description":"L49–L72 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-2/unit-03/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 3 复习与自测","summary":"L49–L72 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 3 复习与自测","link":"/life/english/new-concept/book-2/unit-03/review"},"next":{"text":"第二册：实践与进步 · 单元 3 复习与自测 · 第58–66课","link":"/life/english/new-concept/book-2/unit-03/review-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 3 复习与自测","link":"/life/english/new-concept/book-2/unit-03/review"},"next":{"text":"第二册：实践与进步 · 单元 3 复习与自测 · 第58–66课","link":"/life/english/new-concept/book-2/unit-03/review-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/review-part-01.md","filePath":"life/english/new-concept/book-2/unit-03/review-part-01.md"}'),n={name:"life/english/new-concept/book-2/unit-03/review-part-01.md"};function r(l,e,i,h,p,c){return s(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="第二册-实践与进步-·-单元-3-复习与自测-·-第49–57课" tabindex="-1">第二册：实践与进步 · 单元 3 复习与自测 · 第49–57课 <a class="header-anchor" href="#第二册-实践与进步-·-单元-3-复习与自测-·-第49–57课" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 3 复习与自测 · 第49–57课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-03/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="第二册-实践与进步-·-单元-3-复习与自测" tabindex="-1">第二册：实践与进步 · 单元 3 复习与自测 <a class="header-anchor" href="#第二册-实践与进步-·-单元-3-复习与自测" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 3 复习与自测 {#第二册-实践与进步-·-单元-3-复习与自测}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-2/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-49-·-叙事中的时态与衔接" tabindex="-1">Lesson 49 · 叙事中的时态与衔接 <a class="header-anchor" href="#lesson-49-·-叙事中的时态与衔接" aria-label="Permalink to &quot;Lesson 49 · 叙事中的时态与衔接 {#lesson-49-·-叙事中的时态与衔接}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I was sleeping on the terrace when a gust blew my blanket away.</p><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1 {#练习-1}&quot;">​</a></h3><p>填 blow 的过去式：A gust ___ my blanket away.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> blew</p><p><strong>解析：</strong> blow 的过去式不规则变化为 blew。</p></details><p><strong>表达迁移：</strong> 写一个被天气打断的小计划，包含初衷、意外与实际结果。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I was sleeping on the terrace when a gust blew my blanket away. I woke up and carried the bed indoors. My plan to sleep under the stars lasted only an hour.</p><p>第一句的组织方式：was sleeping 是背景，when 引出 blew；blow 的过去式为 blew，away 表离开原处。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：blowed 不是 blow 的标准过去式，应为 blew；blown 是过去分词。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-049">回看本课</a></p><h2 id="lesson-50-·-过去完成时与先后关系" tabindex="-1">Lesson 50 · 过去完成时与先后关系 <a class="header-anchor" href="#lesson-50-·-过去完成时与先后关系" aria-label="Permalink to &quot;Lesson 50 · 过去完成时与先后关系 {#lesson-50-·-过去完成时与先后关系}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> By the time I asked, the bus had passed my stop.</p><h3 id="练习-1-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-1" aria-label="Permalink to &quot;练习 1 {#练习-1-1}&quot;">​</a></h3><p>填 pass：The bus had ___ my stop.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> passed</p><p><strong>解析：</strong> had 后用过去分词 passed。</p></details><p><strong>表达迁移：</strong> 讲一次坐过站经历，用过去完成时说明发现问题前已经发生的事。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>By the time I asked, the bus had passed my stop. The driver showed me the return route. I bought another ticket and checked every stop.</p><p>第一句的组织方式：By the time 从句 asked 定位过去时刻，had passed 说明更早已发生的事件；my stop 是目的站。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：get out of 常用于小汽车，get off 常用于公共汽车；不能在所有交通方式中机械互换。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-050">回看本课</a></p><h2 id="lesson-51-·-完成进行时与持续活动" tabindex="-1">Lesson 51 · 完成进行时与持续活动 <a class="header-anchor" href="#lesson-51-·-完成进行时与持续活动" aria-label="Permalink to &quot;Lesson 51 · 完成进行时与持续活动 {#lesson-51-·-完成进行时与持续活动}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Tess has been avoiding sweet snacks for two weeks.</p><h3 id="练习-1-2" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-2" aria-label="Permalink to &quot;练习 1 {#练习-1-2}&quot;">​</a></h3><p>填 for/since：She has been practising ___ two weeks.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> for</p><p><strong>解析：</strong> two weeks 是一段时长。</p></details><p><strong>表达迁移：</strong> 描述坚持某个生活习惯的过程，交代持续时间和一次选择。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Tess has been avoiding sweet snacks for two weeks. Today she chose fruit at the café. She said the conversation was a better reward than cake.</p><p>第一句的组织方式：has been avoiding 是完成进行时，for two weeks 是持续长度，sweet snacks 是宾语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：since two weeks 错误，持续长度用 for；since two weeks ago 才引出起点。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-051">回看本课</a></p><h2 id="lesson-52-·-现在完成时与过去时间" tabindex="-1">Lesson 52 · 现在完成时与过去时间 <a class="header-anchor" href="#lesson-52-·-现在完成时与过去时间" aria-label="Permalink to &quot;Lesson 52 · 现在完成时与过去时间 {#lesson-52-·-现在完成时与过去时间}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Fallen leaves have covered the path outside our classroom.</p><h3 id="练习-1-3" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-3" aria-label="Permalink to &quot;练习 1 {#练习-1-3}&quot;">​</a></h3><p>填 have/has：Fallen leaves ___ covered the path.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> leaves 是复数，配 have。</p></details><p><strong>表达迁移：</strong> 写三句校园环境变化，区分观察到的结果和已经完成的清理。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Fallen leaves have covered the path outside our classroom. We collected them in two large bags. A narrow strip is now safe to walk on.</p><p>第一句的组织方式：Fallen leaves 是复数主语，have covered 为完成时；outside our classroom 修饰 path。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：leaves 是 leaf 的复数；不能写 leafs 来表示这里的树叶。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-052">回看本课</a></p><h2 id="lesson-53-·-被动语态与信息重点" tabindex="-1">Lesson 53 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-53-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 53 · 被动语态与信息重点 {#lesson-53-·-被动语态与信息重点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The power failure was caused by a damaged wire.</p><h3 id="练习-1-4" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-4" aria-label="Permalink to &quot;练习 1 {#练习-1-4}&quot;">​</a></h3><p>填 by/from：The failure was caused ___ a damaged wire.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> by</p><p><strong>解析：</strong> be caused by 引出导致事件的原因。</p></details><p><strong>表达迁移：</strong> 写一份非技术故障说明，交代确认原因、发现位置和恢复条件。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The power failure was caused by a damaged wire. An engineer found it behind a panel. The building remained closed until the repair was complete.</p><p>第一句的组织方式：failure 为单数主语，was caused 是过去被动，by 引出原因；damaged 是过去分词作定语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：caused from 不合常见搭配；被动原因用 caused by。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-053">回看本课</a></p><h2 id="lesson-54-·-时间、原因与让步从句" tabindex="-1">Lesson 54 · 时间、原因与让步从句 <a class="header-anchor" href="#lesson-54-·-时间、原因与让步从句" aria-label="Permalink to &quot;Lesson 54 · 时间、原因与让步从句 {#lesson-54-·-时间、原因与让步从句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> As soon as I opened the jar, jam ran over my fingers.</p><h3 id="练习-1-5" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-5" aria-label="Permalink to &quot;练习 1 {#练习-1-5}&quot;">​</a></h3><p>填 run 的过去式：Jam ___ over my fingers.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> ran</p><p><strong>解析：</strong> 具体过去动作使用 ran。</p></details><p><strong>表达迁移：</strong> 描写厨房里连锁发生的两件小意外，用一个紧接关系连接词。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>As soon as I opened the jar, jam ran over my fingers. I reached for a cloth with my clean hand. Unfortunately, the cloth knocked over a cup.</p><p>第一句的组织方式：As soon as 引出开罐动作，ran 为 run 的过去式；over my fingers 描述流过的表面。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：run 的过去式是 ran，过去分词才是 run；不能在简单过去叙事中写 jam run。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-054">回看本课</a></p><h2 id="lesson-55-·-一般过去时与事件顺序" tabindex="-1">Lesson 55 · 一般过去时与事件顺序 <a class="header-anchor" href="#lesson-55-·-一般过去时与事件顺序" aria-label="Permalink to &quot;Lesson 55 · 一般过去时与事件顺序 {#lesson-55-·-一般过去时与事件顺序}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> People once believed that the field contained gold.</p><h3 id="练习-1-6" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-6" aria-label="Permalink to &quot;练习 1 {#练习-1-6}&quot;">​</a></h3><p>填 dig 的过去式：They ___ three holes.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> dug</p><p><strong>解析：</strong> dig 的过去式和过去分词均为 dug。</p></details><p><strong>表达迁移：</strong> 写一个预期落空但产生另一种价值的故事，区分原先信念与发现。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>People once believed that the field contained gold. A survey found only old pottery. The village opened a small historical display instead.</p><p>第一句的组织方式：believed 是主句过去式，that 从句 contained 是当时的信念内容，不代表作者认可它为事实。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：gold 是不可数物质名词，通常不写 a gold；a piece of gold 才表示一块。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-055">回看本课</a></p><h2 id="lesson-56-·-比较级与比较范围" tabindex="-1">Lesson 56 · 比较级与比较范围 <a class="header-anchor" href="#lesson-56-·-比较级与比较范围" aria-label="Permalink to &quot;Lesson 56 · 比较级与比较范围 {#lesson-56-·-比较级与比较范围}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The new car was much faster than the team&#39;s previous model.</p><h3 id="练习-1-7" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-7" aria-label="Permalink to &quot;练习 1 {#练习-1-7}&quot;">​</a></h3><p>选 very/much：The car was ___ faster.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> much</p><p><strong>解析：</strong> much 可以修饰比较级，very 通常不直接修饰比较级。</p></details><p><strong>表达迁移：</strong> 比较两款车辆或设备，给出速度优势及一个代价，不编造真实品牌数据。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The new car was much faster than the team&#39;s previous model. However, its tyres wore out sooner. The engineers chose reliability for the next race.</p><p>第一句的组织方式：much 修饰比较级 faster，than 后明确比较对象；previous model 与 new car 都指车型。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：more faster 重复比较标记；用 faster 或 much faster。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-056">回看本课</a></p><h2 id="lesson-57-·-情态动词的意义与形式" tabindex="-1">Lesson 57 · 情态动词的意义与形式 <a class="header-anchor" href="#lesson-57-·-情态动词的意义与形式" aria-label="Permalink to &quot;Lesson 57 · 情态动词的意义与形式 {#lesson-57-·-情态动词的意义与形式}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Would you like to see a different size?</p><h3 id="练习-1-8" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-8" aria-label="Permalink to &quot;练习 1 {#练习-1-8}&quot;">​</a></h3><p>填 to/for：Would you like ___ try it on?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> would like 后接 to 不定式。</p></details><p><strong>表达迁移：</strong> 写三句服务对话：提供帮助、确认尺寸、回应库存情况。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Would you like to see a different size? The customer asked for a smaller coat. The assistant checked the stock without commenting on her clothes.</p><p>第一句的组织方式：Would you like 后接 to see，a different size 是宾语；would 在此不表过去时间。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Would you like seeing 通常不是提出这次邀请的用法；用 Would you like to see。</p></details><p><a href="/life/english/new-concept/book-2/unit-03/lesson-057">回看本课</a></p>',79)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
